<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
function sd_core_admin_audit() { if ( ! current_user_can( 'sd_view_audit_logs' ) ) { wp_die( esc_html__( 'You are not allowed to view this page.', 'social-discovery-core' ) ); } $rows = sd_core_audit_rows(); ?><div class="wrap"><h1><?php esc_html_e( 'Audit Logs', 'social-discovery-core' ); ?></h1><table class="widefat striped"><thead><tr><th>Actor</th><th>Action</th><th>Target</th><th>Outcome</th><th>Date</th></tr></thead><tbody><?php foreach ( $rows as $row ) : ?><tr><td><?php echo esc_html( $row->actor_id ); ?></td><td><?php echo esc_html( $row->action ); ?></td><td><?php echo esc_html( $row->target_type . ' #' . $row->target_id ); ?></td><td><?php echo esc_html( $row->outcome ); ?></td><td><?php echo esc_html( $row->created_at ); ?></td></tr><?php endforeach; ?></tbody></table></div><?php }
